<template><ContentWrap><el-button type="primary" @click="open=true">新建版本</el-button><el-table :data="rows"><el-table-column prop="code" label="Code"/><el-table-column prop="name" label="名称"/><el-table-column prop="type" label="类型"/><el-table-column prop="version" label="版本"/><el-table-column prop="status" label="状态"/></el-table><el-dialog v-model="open" title="新建 Prompt 版本"><el-form :model="form"><el-input v-model="form.code" placeholder="code"/><el-input v-model="form.name" placeholder="名称"/><el-input v-model="form.content" type="textarea" :rows="10"/></el-form><el-button @click="save">创建不可变版本</el-button></el-dialog></ContentWrap></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{AiPromptApi,type PromptVO}from'@/api/ai/prompt';const rows=ref<PromptVO[]>([]),open=ref(false),form=reactive<any>({code:'',name:'',type:'SYSTEM',content:'',status:'ENABLED'});async function load(){rows.value=(await AiPromptApi.list()).sort((a,b)=>a.code.localeCompare(b.code)||b.version-a.version)}async function save(){await AiPromptApi.create(form);open.value=false;await load()}onMounted(load)</script>